from rdkit import Chem
import pandas as pd

# Assumes a CSV with columns: molecule_id, smiles
df = pd.read_csv("molecules.csv")

bond_map = {
    Chem.BondType.SINGLE:   '-',   # single bond
    Chem.BondType.DOUBLE:   '=',   # double bond
    Chem.BondType.TRIPLE:   '#',   # triple bond
    Chem.BondType.AROMATIC: ':',   # aromatic bond (if present in your scheme)
}

def bond_types(smiles):
    mol = Chem.MolFromSmiles(smiles)
    if mol is None:
        return None
    counts = {}
    for b in mol.GetBonds():
        bt = bond_map.get(b.GetBondType(), str(b.GetBondType()))
        counts[bt] = counts.get(bt, 0) + 1
    return counts

subset = df[df['molecule_id'].isin([f'TR{i:03d}' for i in range(51)])]
for _, row in subset.iterrows():
    print(row['molecule_id'], bond_types(row['smiles']))

