JOIN event e ON b.link_to_event = e.event_id;

SELECT CAST(SUM(CASE WHEN major_name = 'Finance' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN major_name = 'Physics' THEN 1 ELSE 0 END)
FROM member
JOIN major ON member.link_to_major = major.major_id;

SELECT SUM(position = 'Member' AND major_name = 'Business') * 100.0 / COUNT(member_id) AS percentage
FROM member
JOIN major ON member.link_to_major = major.major_id;

SELECT SUM(p.publisher_name = 'DC Comics') - SUM(p.publisher_name = 'Marvel Comics') AS difference
FROM superhero s
JOIN publisher p ON s.publisher_id = p.id;

SELECT ROUND(CAST(SUM(bond_type = '=') AS REAL) / COUNT(bond_id), 5) AS percent
FROM bond
WHERE molecule_id = 'TR008';

SELECT ROUND(SUM(element = 'h') * 100.0 / COUNT(atom_id), 4) AS percent
FROM atom
WHERE molecule_id = 'TR206';

SELECT SUM(CASE WHEN molecule.label = '+' AND atom.element = 'h' THEN 1 ELSE 0 END) * 100.0 / COUNT(molecule.molecule_id) AS percentage
FROM atom
JOIN molecule ON atom.molecule_id = molecule.molecule_id;

SELECT SUM(CASE WHEN molecule.label = '+' AND atom.element = 'cl' THEN 1 ELSE 0 END) * 1.0 / COUNT(molecule.molecule_id) AS percentage
FROM molecule
JOIN atom ON molecule.molecule_id = atom.molecule_id;
